# 屏幕识别三选一（可选：需要 pip install rapidocr_onnxruntime pillow）
# --------------------------------------------------------------------------------------
STOP_WORDS = ("一个", "选择", "重骰", "重新", "重随", "刷新", "选择", "海克斯", "稀有", "棱彩", "黄金", "白银", "确定", "剩余")


class ScreenScanner:
    """截屏 + 文字识别找增幅三选一。为了不拖慢游戏：只用 1 个 CPU 核心、画面先缩小、平时不运行。"""
    CROP = (0.10, 0.08, 0.90, 0.88)   # 在屏幕中间这块区域里找卡片（比例）

    def __init__(self, advisor):
        self.advisor = advisor
        self.force = threading.Event()
        self.ocr, self.kind, self.error = None, None, ""
        try:
            from PIL import ImageGrab  # noqa
            self.grab_fn = ImageGrab.grab
        except ImportError:
            self.error = "未安装 pillow"
            return
        import logging
        logging.getLogger("RapidOCR").setLevel(logging.ERROR)
        light = {"EngineConfig.onnxruntime.intra_op_num_threads": 1,
                 "EngineConfig.onnxruntime.inter_op_num_threads": 1, "Global.use_cls": False}
        try:
            from rapidocr import RapidOCR
            try:
                self.ocr = RapidOCR(params=light)
            except Exception:  # noqa  旧版不认这些参数
                self.ocr = RapidOCR()
            self.kind = "v2"
        except ImportError:
            try:
                from rapidocr_onnxruntime import RapidOCR
                self.ocr, self.kind = RapidOCR(intra_op_num_threads=1), "v1"
            except ImportError:
                self.error = "未安装 OCR 库（运行 start.bat 会自动安装）"
            except Exception as e:  # noqa
                self.error = f"OCR 初始化失败：{e}"
        except Exception as e:  # noqa
            self.error = f"OCR 初始化失败：{e}"
        self.card_x = None    # 最近一次识别到的三张卡在屏幕上的 x 位置（用来判断点了哪张）

    @property
    def available(self):
        return self.ocr is not None

    def grab(self):
        img = self.grab_fn()
        w, h = img.size
        self.screen_size = (w, h)
        c = self.CROP
        self.offset = (int(w * c[0]), int(h * c[1]))
        return img.crop((int(w * c[0]), int(h * c[1]), int(w * c[2]), int(h * c[3])))

    def column_of(self, x, y):
        """屏幕坐标 → 第几张卡；用识别到的卡片位置判断，不在卡片附近回传 None"""
        w, h = getattr(self, "screen_size", (0, 0))
        if not w or not self.card_x:
            return None
        c = self.CROP
        if not (h * c[1] <= y <= h * c[3]):
            return None
        xs = self.card_x
        half = (xs[-1] - xs[0]) / (len(xs) - 1) / 2 if len(xs) > 1 else w * 0.1
        best = min(range(len(xs)), key=lambda i: abs(x - xs[i]))
        return best if abs(x - xs[best]) <= half * 1.05 else None

    def ocr_lines(self, img):
        import numpy as np
        scale = 1.0
        if img.width > 1280:  # 缩小以加速
            scale = 1280 / img.width
            img = img.resize((int(img.width * scale), int(img.height * scale)))
        self.scale = scale
        arr = np.asarray(img.convert("RGB"))
        lines = []
        if self.kind == "v1":
            res, _ = self.ocr(arr)
            items = [(box, txt, sc) for box, txt, sc in (res or [])]
        else:
            r = self.ocr(arr)
            boxes, txts = getattr(r, "boxes", None), getattr(r, "txts", None)
            scores = getattr(r, "scores", None) or [1.0] * len(txts or [])
            items = list(zip(boxes if boxes is not None else [], txts or [], scores))
        for box, txt, sc in items:
            xs, ys = [p[0] for p in box], [p[1] for p in box]
            lines.append((sum(xs) / 4, sum(ys) / 4, simp(str(txt).strip()), float(sc), max(ys) - min(ys)))
        return lines, arr.shape[1]

    @staticmethod
    def _cjk_ratio(s):
        return sum(1 for c in s if "\u4e00" <= c <= "\u9fff") / max(1, len(s))

    def _is_name(self, txt):
        clean = re.sub(r"[\s·•:：\"“”「」()（）0-9%！!？?]", "", txt)
        return clean if (2 <= len(clean) <= 12 and self._cjk_ratio(clean) >= 0.6
                         and not any(w in clean for w in STOP_WORDS)) else None

    def parse(self, lines, width):
        """找「同一高度、左右排开的三个名字」＝三张卡；名字下面、同一栏的文字是描述。
        不假设卡片在屏幕上的位置和间距，窗口大小、分辨率不同也能找到。"""
        import itertools
        good = [(cx, cy, txt, h) for cx, cy, txt, sc, h in lines if sc >= 0.5 and txt]
        names = [(cx, cy, self._is_name(txt), h) for cx, cy, txt, h in good if self._is_name(txt)]
        rows = []
        for combo in itertools.combinations(sorted(names, key=lambda n: n[0]), 3):
            ys = [n[1] for n in combo]
            hmax = max(8.0, max(n[3] for n in combo))
            if max(ys) - min(ys) > 1.2 * hmax:
                continue
            gaps = [combo[1][0] - combo[0][0], combo[2][0] - combo[1][0]]
            if min(gaps) < width * 0.08 or max(gaps) > 1.6 * min(gaps):
                continue          # 三张卡应该大致等距
            rows.append((sum(ys) / 3, max(ys) - min(ys), combo))
        # 从上往下试：卡片名称在描述上面，第一排能通过验证的就是
        for _, _, combo in sorted(rows, key=lambda r: (round(r[0] / 10), r[1])):
            offers = self._validate(combo, good)
            if offers:
                sx, ox = 1 / getattr(self, "scale", 1.0), getattr(self, "offset", (0, 0))[0]
                self.card_x = [ox + n[0] * sx for n in combo]
                return offers
        return None

    def _validate(self, combo, good):
        centers = [n[0] for n in combo]
        half = (centers[2] - centers[0]) / 4
        offers = []
        for cx0, cy0, name, h0 in combo:
            desc = [txt for cx, cy, txt, h in sorted(good, key=lambda g: g[1])
                    if abs(cx - cx0) <= half and cy > cy0 + h0 * 0.5 and cy < cy0 + h0 * 14
                    and not (len(txt) <= 8 and any(w in txt for w in STOP_WORDS))]
            offers.append((name, " ".join(desc)))
        # 防误识别（例如商店的三张推荐装备卡）：名字要能对上增幅库，或描述像增幅
        item_like = sum(1 for n, _ in offers if n in self.advisor.gd_item_names())
        if item_like >= 2:
            return None
        known = sum(1 for n, _ in offers if self.advisor.match_name(n, 0.7))
        described = sum(1 for _, d in offers if len(d) >= 6 and keyword_tags(d))
        if not (known >= 2 or (known >= 1 and described >= 2) or described >= 3):
            return None
        return offers

    def scan_full(self):
        img = self.grab()
        lines, width = self.ocr_lines(img)
        return self.parse(lines, width), img, lines, width

    def scan(self, debug=False):
        img = self.grab()
        lines, width = self.ocr_lines(img)
        offers = self.parse(lines, width)
        if debug or offers is None and getattr(self, "save_failed", False):
            self.save_debug(img, lines, width, offers)
        return offers

    def save_debug(self, img, lines, width, offers):
        d = os.path.join(APP_DIR, "debug")
        os.makedirs(d, exist_ok=True)
        stamp = time.strftime("%H%M%S")
        img.save(os.path.join(d, f"scan_{stamp}.png"))
        with open(os.path.join(d, f"scan_{stamp}.txt"), "w", encoding="utf-8") as f:
            f.write(f"宽度 {width}\n结果 {offers}\n\n")
            for cx, cy, txt, sc, _h in sorted(lines, key=lambda x: (x[1], x[0])):
                f.write(f"x={cx:.0f} y={cy:.0f} {sc:.2f} {txt}\n")
        files = sorted(x for x in os.listdir(d) if x.startswith("scan_"))
        for old in files[:-20]:        # 只保留最近 10 组
            try:
                os.remove(os.path.join(d, old))
            except OSError:
                pass


class ClickWatcher:
    """三选一画面出现时，每 20 毫秒看一次鼠标左键有没有按下、按在哪里（Windows GetAsyncKeyState），
    用来自动记录你选了哪张卡。只读鼠标状态，不挂钩、不碰游戏；其他时间完全不运行。"""

    def __init__(self):
        self.clicks = []                 # [(时间, x, y)]
        self.active = threading.Event()
        self.available = sys.platform.startswith("win")
        if self.available:
            threading.Thread(target=self._run, daemon=True).start()

    def _run(self):
        import ctypes

        class POINT(ctypes.Structure):
            _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]
        user32 = ctypes.windll.user32
        vk = 0x02 if user32.GetSystemMetrics(23) else 0x01   # 左右键互换时改看右键
        down = False
        while True:
            if not self.active.is_set():
                self.active.wait()
                down = True        # 刚开始时若键正按着，不算一次点击
            pressed = bool(user32.GetAsyncKeyState(vk) & 0x8000)
            if pressed and not down:
                pt = POINT()
                user32.GetCursorPos(ctypes.byref(pt))
                self.clicks = (self.clicks + [(time.time(), pt.x, pt.y)])[-20:]
            down = pressed
            time.sleep(0.02)


class MockClickWatcher:
    """--mock：38 秒时模拟点第二张卡"""
    available = True

    def __init__(self, source):
        self.source, self.active = source, threading.Event()

    @property
    def clicks(self):
        t = self.source.t0 + 38
        return [(t, 960, 540)] if time.time() >= t else []


def _same_name(a, b):
    import difflib
    return a == b or difflib.SequenceMatcher(None, a, b).ratio() >= 0.75


def same_offer(a, b):
    return bool(a) and bool(b) and len(a) == len(b) and all(_same_name(x, y) for x, y in zip(a, b))


class HotkeyWatcher:
    """全局快捷键（默认 F8）：每 50 毫秒看一次这个键有没有按下，几乎不占 CPU。只读键盘状态，不挂钩。"""
    KEYS = {f"F{i}": 0x6F + i for i in range(1, 13)}

    def __init__(self, name="F8"):
        self.name = name.upper()
        self.vk = self.KEYS.get(self.name)
        self.hit = threading.Event()
        self.available = sys.platform.startswith("win") and self.vk is not None
        if self.available:
            threading.Thread(target=self._run, daemon=True).start()

    def _run(self):
        import ctypes
        user32 = ctypes.windll.user32
        down = False
        while True:
            pressed = bool(user32.GetAsyncKeyState(self.vk) & 0x8000)
            if pressed and not down:
                self.hit.set()
            down = pressed
            time.sleep(0.05)


def scanner_loop(engine, scanner, stop, enabled, interval=3.0, clicker=None, hotkey=None):
    """
    默认「手动」：按按钮或快捷键才识别（平时完全不跑，不会拖慢游戏）。
    * 按一下：马上识别，最多试 3 次；识别到后在三选一期间每 2 秒低频检查一次，
      用来发现重骰（自动重新评分）、界面关闭（配合点击记录你选的卡）；再按一下＝立即刷新。
    * 勾选「自动识别」才会一直每 3 秒扫一次（较耗 CPU）。
    """
    last, misses, active = None, 0, False
    cur, changed_at = None, 0.0
    tries = 0
    while not stop.is_set():
        forced = scanner.force.is_set() or bool(hotkey and hotkey.hit.is_set())
        if forced:
            scanner.force.clear()
            if hotkey:
                hotkey.hit.clear()
            tries = 3
            engine.q.put(("status", "识别中…"))
        run = scanner.available and (forced or active or tries > 0 or (enabled.is_set() and engine.connected))
        if run:
            try:
                offers, img, lines, width = scanner.scan_full()
            except Exception as e:  # noqa
                engine.q.put(("status", f"识别出错：{e}"))
                offers, img, lines, width = None, None, [], 0
            if offers:
                tries, misses = 0, 0
                names = [n for n, _ in offers]
                known = sum(1 for n in names if engine.advisor.match_name(n, 0.75))
                if forced or not active or known == len(names) or same_offer(last, names):
                    if not same_offer([n for n, _ in cur or []], names):
                        cur, changed_at = offers, time.time()   # 新的三选一或重骰
                    engine.set_auto(offers)
                    if not active and clicker is not None:
                        clicker.active.set()
                    if forced or not active:
                        engine.q.put(("status", "已识别：" + " / ".join(names)))
                    active = True
                last = names
            else:
                last = None
                if tries > 0:                      # 手动触发：再试几次
                    tries -= 1
                    if tries == 0 and not active:
                        engine.q.put(("status", "没识别到三选一（截图已存）"))
                        if img is not None:
                            try:
                                scanner.save_debug(img, lines, width, None)
                            except Exception:  # noqa
                                pass
                if active:
                    misses += 1
                    pick = _find_pick(scanner, clicker, cur, changed_at, engine)
                    if misses >= 3 or (pick is not None and misses >= 2):
                        engine.set_auto([])
                        if pick is not None:
                            engine.add_pick(pick)
                        if clicker is not None:
                            clicker.active.clear()
                            if hasattr(clicker.clicks, "clear"):
                                clicker.clicks.clear()
                        active, cur = False, None
        if tries > 0:
            wait = 0.4
        elif active:
            wait = 2.0
        elif enabled.is_set():
            wait = interval
        else:
            wait = 0.1                                 # 只是在等你按快捷键
        end = time.time() + wait
        while time.time() < end and not stop.is_set():
            if scanner.force.is_set() or (hotkey and hotkey.hit.is_set()):
                break
            time.sleep(0.05)


def _find_pick(scanner, clicker, cur, changed_at, engine):
    """关闭前最后一次、落在卡片上的点击 → 那张卡就是你选的"""
    if clicker is None or not cur:
        return None
    rect = getattr(engine, "overlay_rect", None)   # 点在挂件上的不算
    for t, x, y in reversed(list(clicker.clicks)):
        if t < changed_at or time.time() - t > 12:
            continue
        if rect and rect[0] <= x <= rect[2] and rect[1] <= y <= rect[3]:
            continue
        col = scanner.column_of(x, y)
        if col is not None and col < len(cur):
            return cur[col][0]
    return None


class LiveSource:
    def fetch(self):
        return http_json(LIVE_URL, timeout=2, local=True)


