class Engine:
    def __init__(self, gd, source, interval=1.5, stats=None):
        self.gd, self.source, self.interval = gd, source, interval
        self.advisor = Advisor(gd, stats)
        self.stats_dirty = False
        if stats is not None:
            def ready():
                self.stats_dirty = True
                self.wake.set()
            stats.on_ready = ready
        self.manual = {"mine": [], "cand": [], "ally": [], "enemy": [], "auto": [], "picked": []}
        self.overlay_rect = None
        self.wake = threading.Event()
        self.connected = False
        self.lock = threading.Lock()
        self.q = queue.Queue()
        self.last_sig = None
        self.last_state = None
        self.manual_dirty = False
        self.history = []
        self.pending_data = None       # (gd, stats, 说明)：新版本数据，等不在对局中时换上
        self.updater = None

    def apply_pending(self):
        gd, stats, msg = self.pending_data
        self.pending_data = None
        old_ds = self.advisor.stats.dataset if self.advisor.stats else "all"
        if stats is not None:
            stats.dataset = old_ds
            stats.on_ready = self.advisor.stats.on_ready if self.advisor.stats else None
        # 原地换掉（屏幕识别等地方持有同一个 advisor）
        fresh = Advisor(gd, stats)
        self.advisor.__dict__.clear()
        self.advisor.__dict__.update(fresh.__dict__)
        self.gd = gd
        self.last_sig = None
        n = clean_old_cache(data_versions(gd, stats))
        self.q.put(("data", msg + (f"（清理旧缓存 {n} 个）" if n else "")))

    def set_manual(self, key, text):
        vals = [x.strip() for x in re.split(r"[,，、;；\s]+", text) if x.strip()]
        with self.lock:
            if key == "mine" and self.manual.get("picked"):
                # 输入框里显示的是「手动 + 自动记录」的全部；用户改了就以输入框为准
                self.manual["picked"] = []
                self.manual_dirty = True
            if self.manual.get(key) != vals:
                self.manual[key] = vals
                self.manual_dirty = True
                self.wake.set()

    def add_pick(self, name):
        with self.lock:
            if name in self.manual.get("picked", []) or name in self.manual.get("mine", []):
                return
            self.manual.setdefault("picked", []).append(name)
            self.manual_dirty = "picked:" + name
        self.wake.set()

    def set_auto(self, offers):
        """offers: [(name, desc)]，空列表表示三选一界面消失"""
        vals = [f"{n}|{d}" for n, d in offers]
        with self.lock:
            old = [s.split("|", 1)[0] for s in self.manual["auto"]]
            new = [n for n, _ in offers]
            if same_offer(old, new) or (not old and not new):
                return
            self.manual["auto"] = vals
            self.manual_dirty = ("auto_reroll" if old and vals else "auto_on" if vals else "auto_off")
        self.wake.set()

    def step(self):
        if self.pending_data and (not self.connected or self.last_state is None):
            self.apply_pending()           # 只在对局外 / 新一局开始前换数据
        try:
            raw = self.source.fetch()
            state = parse_live(raw)
        except Exception:
            self.last_sig = None
            self.last_state = None
            self.connected = False
            return ("status", "等待对局…")
        self.connected = True
        if state[2] is None:
            return ("status", "已连接，等待玩家数据…")
        with self.lock:
            manual = {k: list(v) for k, v in self.manual.items()}
            dirty, self.manual_dirty = self.manual_dirty, False
        sig = signature(state, manual)
        lsig = live_signature(state)
        stats_new, self.stats_dirty = self.stats_dirty, False
        if sig == self.last_sig and lsig == getattr(self, "last_lsig", None) and not stats_new:
            return ("status", "监控中")
        quiet = sig == self.last_sig and not stats_new  # 只有阵亡/击杀/血量变化：更新战术，不弹出窗口
        changes = (describe_live(self.gd, self.last_state, state) if quiet
                   else describe_changes(self.gd, self.last_state, state, dirty))
        if stats_new:
            changes = ["已载入网上胜率数据"] + [c for c in changes if c != "阵容信息变化"]
            self.advisor._ema_cid = None     # 新数据进来：重新排序，不沿用旧的平滑结果
        self.last_sig, self.last_lsig, self.last_state = sig, lsig, state
        rec = self.advisor.analyze(state, manual)
        rec["changes"] = changes
        rec["quiet"] = quiet
        rec["time"] = time.strftime("%H:%M:%S")
        self.history.append(rec)
        self.history = self.history[-30:]
        return ("rec", rec)

    def run(self, stop):
        while not stop.is_set():
            try:
                self.q.put(self.step())
            except Exception as e:  # 推荐演算法异常不应让挂件崩溃
                self.q.put(("status", f"分析出错：{e}"))
            self.wake.wait(self.interval)  # 手动输入 / 识别到新增幅时会被立即唤醒
            self.wake.clear()



# --------------------------------------------------------------------------------------
# 程序新版本提醒（只提醒，下载与覆盖由你自己决定）
# --------------------------------------------------------------------------------------
def ver_tuple(v):
    return tuple(int(x) for x in re.findall(r"\d+", str(v))[:4])


def check_app_version():
    """返回 (新版本信息 或 None, 错误)；新版本信息是仓库里的 version.json：{version, date, notes}"""
    err = ""
    for url in VERSION_URLS:
        try:
            m = http_json(url, timeout=12)
            return (m if ver_tuple(m.get("version")) > ver_tuple(APP_VERSION) else None), ""
        except Exception as e:  # noqa
            err = str(e)
    return None, err


# --------------------------------------------------------------------------------------
# 数据版本更新：跟着游戏 / 海斗版本走
# --------------------------------------------------------------------------------------
def load_all(lang, bracket="all", use_stats=True, log=print, force=False):
    """下载（或读缓存）全部数据：游戏装备/英雄/增幅 + 海斗胜率、商店、增幅池、平衡调整"""
    gd = GameData.load(lang, log=log)
    stats = None
    if use_stats:
        stats = StatsProvider(lang, log=log)
        stats.dataset = bracket
        stats.load_version(force=force)
        extra = stats.load_augments()
        if extra:
            gd.merge_augments(extra)
            allow = stats.load_items() or set()
            stats.load_spell_names()
            stats.load_balance()
            stats.game_version = ".".join(str(gd.version).split(".")[:2])
            log(f"[胜率] {stats.label()}：海斗增幅 {len(extra)} 个，商店成品装备 {len(allow)} 件")
    return gd, stats


def data_versions(gd, stats):
    sv = (stats.version or {}) if stats else {}
    return (str(gd.version), sv.get("dataPath", ""), sv.get("resourcePath", ""))


def clean_old_cache(keep):
    """删掉旧版本的缓存文件（每个版本几十 MB，不清会越积越多）"""
    game_ver, data_path, res_path = keep
    dp, rp = data_path.replace("/", "_"), res_path.replace("/", "_")
    removed = 0
    try:
        for fn in os.listdir(APP_DIR):
            if (fn.startswith("kit_") and not fn.startswith(f"kit_{game_ver}_")) or \
                    (fn.startswith("ver_") and not fn.startswith(f"ver_{game_ver}_")):
                os.remove(os.path.join(APP_DIR, fn))
                removed += 1
        kd = os.path.join(APP_DIR, "aramkit")
        for fn in os.listdir(kd) if os.path.isdir(kd) else []:
            if fn == "versions.json":
                continue
            if (dp and fn.startswith(("champ_", "sa_")) and dp not in fn) or \
                    (rp and fn.startswith(("aug_", "items_", "champs_", "ss_")) and rp not in fn):
                os.remove(os.path.join(kd, fn))
                removed += 1
    except OSError:
        pass
    return removed


class DataUpdater:
    """背景检查新版本：不在对局中时每 30 分钟一次、每局结束时一次、也可手动。
    有新版本就在背景下载好，等到不在对局中（或新一局开始前）再换上，不会打断正在打的一局。"""
    EVERY = 30 * 60

    def __init__(self, engine, lang, use_stats=True):
        self.engine, self.lang, self.use_stats = engine, lang, use_stats
        self.last_check = time.time()          # 启动时刚载入过
        self.now = threading.Event()
        self.busy = False
        self.last_result = ""
        self.app_new = None
        self.last_app_check = time.time() - 6 * 3600 + 15    # 启动 15 秒后查一次程序新版本

    def check_app(self, manual=False):
        self.last_app_check = time.time()
        m, err = check_app_version()
        if m:
            self.app_new = m
            self.engine.q.put(("appupd", m))
        elif manual:
            self.engine.q.put(("data", "检查程序新版本失败" if err else f"程序已是最新 v{APP_VERSION}"))

    def check_now(self):
        self.now.set()

    def _remote_versions(self):
        game = http_json(DDRAGON + "/api/versions.json", timeout=10)[0]
        dp = rp = ""
        if self.use_stats:
            v = http_json(f"{ARAMKIT}/data/versions.json", timeout=15)
            cur = next((x for x in v.get("versions", []) if x.get("version") == v.get("latest")),
                       (v.get("versions") or [{}])[0])
            dp, rp = cur.get("dataPath", ""), cur.get("resourcePath", "")
        return game, dp, rp

    def check(self, manual=False):
        eng = self.engine
        self.busy = True
        try:
            cur = data_versions(eng.gd, eng.advisor.stats)
            try:
                remote = self._remote_versions()
            except Exception:  # noqa
                self.last_result = "检查更新失败（连不上数据网站）"
                if manual:
                    eng.q.put(("data", self.last_result))
                return
            changed = [n for n, a, b in zip(("游戏数据", "海斗胜率", "海斗资料"), cur, remote) if b and a != b]
            if not changed:
                self.last_result = "已是最新 " + ".".join(cur[0].split(".")[:2])
                if manual:
                    eng.q.put(("data", self.last_result))
                return
            eng.q.put(("data", "发现新版本，背景下载中…"))
            bracket = eng.advisor.stats.dataset if eng.advisor.stats else "all"
            gd, stats = load_all(self.lang, bracket, self.use_stats, log=lambda m: None, force=True)
            new = data_versions(gd, stats)
            if new == cur:
                self.last_result = "已是最新 " + ".".join(cur[0].split(".")[:2])
                return
            what = []
            if new[0] != cur[0]:
                what.append(f"游戏 {cur[0]} → {new[0]}")
            if new[1] != cur[1] and stats:
                what.append(f"海斗胜率 {stats.version.get('version', '')}（{stats.version.get('dataDate', '')}）")
            elif new[2] != cur[2]:
                what.append("海斗增幅/装备/平衡调整")
            eng.pending_data = (gd, stats, "数据已更新：" + "，".join(what))
            eng.wake.set()
        finally:
            self.last_check = time.time()
            self.busy = False

    def run(self, stop):
        was_connected = False
        while not stop.is_set():
            manual = self.now.wait(20)
            self.now.clear()
            conn = self.engine.connected
            game_over = was_connected and not conn
            was_connected = conn
            due = time.time() - self.last_check > self.EVERY
            if manual or (not conn and (game_over or due)):   # 对局中不检查，不占网络
                try:
                    self.check(manual)
                except Exception as e:  # noqa
                    self.engine.q.put(("data", f"更新出错：{e}"))
            if manual or (not conn and time.time() - self.last_app_check > 6 * 3600):
                try:
                    self.check_app(manual)
                except Exception:  # noqa
                    pass


def start_updater(engine, lang, use_stats, stop):
    up = DataUpdater(engine, lang, use_stats)
    engine.updater = up
    threading.Thread(target=up.run, args=(stop,), daemon=True).start()
    return up

