def format_rec(rec):
    lines = [f"\n==== {rec['time']} ｜ " + "；".join(rec["changes"]) + " ====", rec["summary"]]
    g = rec.get("guide") or {}
    if g.get("combos") or g.get("skills"):
        lines.append("【英雄玩法】")
        for x in (g.get("balance"), g.get("skills"), g.get("spells")):
            if x:
                lines.append(" " + x)
        for c, note in g.get("combos", []):
            lines.append(f" 连招：{c}｜{note}")
        if g.get("style"):
            lines.append(" 玩法：" + g["style"])
    lines.append("【战术建议】")
    for _, txt, urgent in rec.get("tips", []):
        lines.append((" ⚠ " if urgent else " • ") + txt)
    lines.append("【推荐装备】")
    for i, it in enumerate(rec["items"], 1):
        wr = f"胜率{it['wr'] * 100:.1f}% " if it.get("wr") else ""
        lines.append(f" {i}. {it['name']:<10} {it['score']:>3}分  [{wr}{it.get('hint', '')}] {it['reason']}")
    lines.append("【三选一评分】" if rec["cand_mode"] else "【推荐增幅】")
    for i, a in enumerate(rec["augs"], 1):
        mark = " ←选它" if rec["cand_mode"] and i == 1 else ""
        wr = f"[胜率{a['wr'] * 100:.1f}%] " if a.get("wr") else ""
        lines.append(f" {i}. {a['name']:<10} {a['score']:>3}分  {wr}{a['reason']}{mark}")
    return "\n".join(lines)


def start_scanner(engine, scanner, stop, enabled):
    if scanner is not None:
        threading.Thread(target=scanner_loop, args=(engine, scanner, stop, enabled),
                         kwargs={"clicker": getattr(engine, "clicker", None),
                                 "hotkey": getattr(engine, "hotkey", None)}, daemon=True).start()


def run_console(engine, scanner=None):
    print("海斗助手（控制台模式）。可输入：候选 A,B,C / 我的 X / 敌方 Y / 队友 Z，回车应用；Ctrl+C 退出")
    stop, enabled = threading.Event(), threading.Event()
    enabled.set()
    threading.Thread(target=engine.run, args=(stop,), daemon=True).start()
    start_scanner(engine, scanner, stop, enabled)
    if scanner is not None and not scanner.available:
        print("· 屏幕识别不可用：", scanner.error)
    keymap = {"候选": "cand", "我的": "mine", "敌方": "enemy", "队友": "ally"}

    def reader():
        for line in sys.stdin:
            parts = line.strip().split(maxsplit=1)
            if parts and parts[0] in keymap:
                engine.set_manual(keymap[parts[0]], parts[1] if len(parts) > 1 else "")
    threading.Thread(target=reader, daemon=True).start()
    last_status = None
    try:
        while True:
            kind, payload = engine.q.get()
            if kind == "rec":
                print(format_rec(payload), flush=True)
            elif kind == "appupd":
                print(f"· 海斗助手有新版本 v{payload.get('version')}：" + "；".join(payload.get("notes", [])[:3]) +
                      f"\n  下载：{REPO_URL}", flush=True)
            elif payload != last_status:
                print("·", payload, flush=True)
                last_status = payload
    except KeyboardInterrupt:
        stop.set()


# --------------------------------------------------------------------------------------
# 输出：悬浮窗
# --------------------------------------------------------------------------------------
def load_ui_cfg():
    try:
        with open(os.path.join(APP_DIR, "ui.json"), encoding="utf-8") as f:
            return json.load(f)
    except Exception:  # noqa
        return {}


def save_ui_cfg(cfg):
    try:
        os.makedirs(APP_DIR, exist_ok=True)
        with open(os.path.join(APP_DIR, "ui.json"), "w", encoding="utf-8") as f:
            json.dump(cfg, f)
    except Exception:  # noqa
        pass


def run_overlay(engine, alpha=0.92, scanner=None, scale=None):
    """紧凑悬浮窗：出装 / 增幅 / 玩法 三个分页，一次只看一页；平时收成一行。"""
    import tkinter as tk
    import tkinter.font as tkfont

    # ---------- 配色 ----------
    BG, CARD, CARD_HI, HEAD = "#0f1218", "#161b25", "#1d2431", "#0a0d12"
    FG, SUB, DIM, GOLD = "#e6e9ef", "#8a93a6", "#5b6477", "#c8aa6e"
    GREEN, YELLOW, GREY, ORANGE = "#3ddc84", "#f5c542", "#7b8497", "#ff8a3d"
    FAMILY = "Microsoft YaHei UI" if sys.platform.startswith("win") else "Noto Sans CJK SC"

    def score_color(s):
        return GREEN if s >= 80 else YELLOW if s >= 65 else GREY

    cfg = load_ui_cfg()
    root = tk.Tk()
    root.title("海斗助手")
    root.overrideredirect(True)
    root.attributes("-topmost", True)
    try:
        root.attributes("-alpha", alpha)
    except tk.TclError:
        pass
    root.configure(bg=BG, highlightthickness=1, highlightbackground="#2a3140")
    dpi = max(1.0, root.winfo_fpixels("1i") / 96.0)
    sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
    st = {"k": scale or cfg.get("scale", 1.0), "x": cfg.get("x"), "y": cfg.get("y", int(sh * 0.22)),
          "pinned": False, "expanded": True, "hold_until": 0.0, "inside_since": None, "left_at": 0.0, "last_key": None,
          "tab": "items", "user_tab": False, "tab_before_cand": None}
    if st["x"] is None:
        st["x"] = sw - int(300 * dpi * st["k"]) - 12
    st["x"], st["y"] = min(max(0, st["x"]), sw - 120), min(max(0, st["y"]), sh - 60)

    BASE = {"title": (10, "bold"), "tab": (9, "bold"), "name": (10, "bold"), "score": (11, "bold"),
            "small": (8, "normal"), "tip": (9, "normal"), "icon": (10, "normal")}
    F = {k: tkfont.Font(family=FAMILY, size=v, weight=w) for k, (v, w) in BASE.items()}
    wraps = []

    def W():
        return int(300 * dpi * st["k"])

    def fit():
        root.update_idletasks()
        need = root.winfo_reqheight()
        root.geometry(f"{W()}x{min(need, sh - st['y'] - 8)}+{st['x']}+{st['y']}")

    def persist():
        c = load_ui_cfg()
        c.update({"scale": st["k"], "x": st["x"], "y": st["y"]})
        save_ui_cfg(c)

    def set_scale(k):
        st["k"] = k
        for key, (v, w) in BASE.items():
            F[key].configure(size=max(6, round(v * k)))
        for lb in wraps:
            lb.config(wraplength=W() - int(28 * dpi))
        fit()
        persist()

    # ---------- 小工具：悬停提示 ----------
    tip_win = {"w": None}

    def kill_tip():
        if tip_win["w"] is not None:
            try:
                tip_win["w"].destroy()
            except tk.TclError:
                pass
            tip_win["w"] = None

    def hover(widget, text_fn):
        def enter(e):
            kill_tip()
            text = text_fn()
            if not text:
                return
            tw = tk.Toplevel(root)
            tw.overrideredirect(True)
            tw.attributes("-topmost", True)
            tk.Label(tw, text=text, bg="#232b3a", fg=FG, font=F["small"], justify="left",
                     wraplength=int(260 * dpi * st["k"]), padx=8, pady=6).pack()
            tw.update_idletasks()
            x = root.winfo_rootx() - tw.winfo_reqwidth() - 6
            if x < 0:
                x = root.winfo_rootx() + root.winfo_width() + 6
            tw.geometry(f"+{x}+{e.y_root - 10}")
            tip_win["w"] = tw

        def leave(_e):
            kill_tip()
        widget.bind("<Enter>", enter, add="+")
        widget.bind("<Leave>", leave, add="+")

    # ---------- 标题栏 ----------
    header = tk.Frame(root, bg=HEAD)
    header.pack(fill="x")
    dot = tk.Label(header, text="●", bg=HEAD, fg=GREY, font=F["small"])
    dot.pack(side="left", padx=(8, 2), pady=5)
    title = tk.Label(header, text="海斗助手", bg=HEAD, fg=GOLD, font=F["title"])
    title.pack(side="left")
    status = tk.Label(header, text="", bg=HEAD, fg=DIM, font=F["small"])
    status.pack(side="left", padx=6)

    def set_status(text):
        """没有别的消息时，标题栏显示新版本提醒（金色，可点）"""
        if not text and st.get("app_new"):
            status.config(text=f"⇪ 新版 v{st['app_new'].get('version', '')}", fg=GOLD, cursor="hand2")
        else:
            status.config(text=text, fg=DIM, cursor="")

    def open_download(_e=None):
        if st.get("app_new"):
            import webbrowser
            webbrowser.open(REPO_URL)
    status.bind("<Button-1>", open_download, add="+")
    hover(status, lambda: ("海斗助手 v{} 已发布（你现在是 v{}）\n".format(st["app_new"].get("version"), APP_VERSION) +
                           "\n".join("· " + x for x in st["app_new"].get("notes", [])[:6]) +
                           "\n点一下打开下载页，下载后解压覆盖旧文件") if st.get("app_new") else "")

    def hbtn(text, cmd, fg=SUB, bg=HEAD):
        b = tk.Label(header, text=text, bg=bg, fg=fg, font=F["small"], padx=7, pady=3, cursor="hand2")
        b.pack(side="right", padx=(0, 2))
        b.bind("<Button-1>", lambda e: cmd())
        b.bind("<Enter>", lambda e: b.config(fg=FG), add="+")
        b.bind("<Leave>", lambda e: b.config(fg=fg), add="+")
        return b

    menu_btn = hbtn("⋯", lambda: open_menu())
    pin_btn = hbtn("📌", lambda: toggle_pin(), fg=GOLD if st["pinned"] else SUB)
    hk = getattr(getattr(engine, "hotkey", None), "name", "")
    hbtn(f"识别 {hk}".strip(), lambda: force_scan(), fg=FG, bg="#2b3a57")

    drag = {}

    def start_drag(e):
        drag["x"], drag["y"] = e.x_root - root.winfo_x(), e.y_root - root.winfo_y()

    def do_drag(e):
        st["x"], st["y"] = e.x_root - drag["x"], e.y_root - drag["y"]
        root.geometry(f"+{st['x']}+{st['y']}")
    for w in (header, title, status, dot):
        w.bind("<ButtonPress-1>", start_drag, add="+")
        w.bind("<B1-Motion>", do_drag)
        w.bind("<ButtonRelease-1>", lambda e: persist())

    # ---------- 单行模式 ----------
    mini = tk.Label(root, text="等待对局…", bg=BG, fg=FG, font=F["tip"], anchor="w", justify="left", padx=8, pady=5)
    wraps.append(mini)

    # ---------- 展开内容 ----------
    body = tk.Frame(root, bg=BG)
    body.pack(fill="both", expand=True)
    summary = tk.Label(body, text="", bg=BG, fg=SUB, font=F["small"], anchor="w", justify="left", padx=8)
    summary.pack(fill="x", pady=(5, 0))
    wraps.append(summary)
    alert = tk.Label(body, text="", bg="#3a2412", fg=ORANGE, font=F["tip"], anchor="w", justify="left", padx=8, pady=3)
    wraps.append(alert)

    tabs_bar = tk.Frame(body, bg=BG)
    tabs_bar.pack(fill="x", padx=6, pady=(6, 2))
    tab_btns = {}

    def select_tab(name, user=False):
        st["tab"] = name
        if user:
            st["user_tab"] = True
        for k, (lb, ul) in tab_btns.items():
            on = k == name
            lb.config(fg=FG if on else DIM)
            ul.config(bg=GOLD if on else BG)
        for k, fr in pages.items():
            fr.pack_forget()
        pages[name].pack(fill="x", padx=6, pady=(4, 4), before=footer)
        fit()

    for key, text in (("items", "出装"), ("augs", "增幅"), ("guide", "玩法")):
        holder = tk.Frame(tabs_bar, bg=BG)
        holder.pack(side="left", padx=(2, 10))
        lb = tk.Label(holder, text=text, bg=BG, fg=DIM, font=F["tab"], cursor="hand2")
        lb.pack()
        ul = tk.Frame(holder, bg=BG, height=2)
        ul.pack(fill="x")
        lb.bind("<Button-1>", lambda e, k=key: select_tab(k, user=True))
        tab_btns[key] = (lb, ul)
    tk.Frame(body, bg="#232a36", height=1).pack(fill="x", padx=8)

    pages = {k: tk.Frame(body, bg=BG) for k in ("items", "augs", "guide")}

    def make_rows(parent, n):
        rows = []
        for _ in range(n):
            fr = tk.Frame(parent, bg=CARD, cursor="arrow")
            top = tk.Frame(fr, bg=CARD)
            top.pack(fill="x")
            sc = tk.Label(top, text="", bg=CARD_HI, fg=FG, font=F["score"], width=3)
            sc.pack(side="left", padx=(0, 6), fill="y")
            nm = tk.Label(top, text="", bg=CARD, fg=FG, font=F["name"], anchor="w")
            nm.pack(side="left")
            meta = tk.Label(top, text="", bg=CARD, fg=SUB, font=F["small"], anchor="e")
            meta.pack(side="right", padx=6)
            rs = tk.Label(fr, text="", bg=CARD, fg=SUB, font=F["small"], anchor="w", justify="left")
            rs.pack(fill="x", padx=(6, 6), pady=(0, 3))
            full = {"text": ""}
            for w in (fr, nm, rs, meta, sc):
                hover(w, lambda full=full: full["text"])
            rows.append({"fr": fr, "sc": sc, "nm": nm, "meta": meta, "rs": rs, "full": full})
        return rows

    def short(text, n):
        n = int(n * st["k"] ** -0.2) if st["k"] > 1 else int(n / st["k"])
        return text if len(text) <= n else text[:n - 1] + "…"

    # 出装页：战术（最多 2 条）＋鞋子＋装备
    tips_box = tk.Frame(pages["items"], bg=BG)
    tips_box.pack(fill="x")
    tip_lbls = []
    for _ in range(2):
        lb = tk.Label(tips_box, text="", bg=BG, fg=FG, font=F["tip"], anchor="w", justify="left")
        wraps.append(lb)
        tip_lbls.append(lb)
    item_rows = make_rows(pages["items"], 4)

    # 增幅页
    aug_head = tk.Label(pages["augs"], text="", bg=BG, fg=SUB, font=F["small"], anchor="w")
    aug_head.pack(fill="x", pady=(0, 2))
    aug_rows = make_rows(pages["augs"], 4)
    mine_lbl = tk.Label(pages["augs"], text="", bg=BG, fg=DIM, font=F["small"], anchor="w", justify="left")
    wraps.append(mine_lbl)

    # 玩法页
    guide_lbl = tk.Label(pages["guide"], text="", bg=CARD, fg=FG, font=F["tip"], anchor="w", justify="left",
                         padx=8, pady=6)
    guide_lbl.pack(fill="x")
    wraps.append(guide_lbl)

    footer = tk.Label(body, text="", bg=BG, fg=DIM, font=F["small"], anchor="w", padx=8, cursor="hand2")
    footer.pack(fill="x", pady=(0, 4))
    footer.bind("<Button-1>", lambda e: switch_bracket())

    def footer_tip():
        so = S()
        up = getattr(engine, "updater", None)
        lines = [f"海斗助手 v{APP_VERSION}", f"游戏数据 {engine.gd.version}"]
        if so is not None and so.version:
            lines.append(f"海斗胜率 ARAMKit {so.version.get('version', '')}（{so.version.get('dataDate', '')}）")
        if st.get("data_msg"):
            lines.append(st["data_msg"])
        elif up is not None and up.last_result:
            lines.append(up.last_result)
        lines.append("点一下切换 全部分段 / 高分段")
        return "\n".join(lines)
    hover(footer, footer_tip)

    # ---------- 展开 / 收起 ----------
    def set_expanded(flag):
        flag = flag or st["pinned"]
        if flag == st["expanded"]:
            return
        st["expanded"] = flag
        if flag:
            mini.pack_forget()
            body.pack(fill="both", expand=True)
        else:
            body.pack_forget()
            mini.pack(fill="x")
        fit()

    def pointer_inside():
        try:
            px, py = root.winfo_pointerxy()
            x, y = root.winfo_rootx(), root.winfo_rooty()
            return x <= px < x + root.winfo_width() and y <= py < y + root.winfo_height()
        except tk.TclError:
            return False

    def auto_collapse():
        """每次 poll 调用：鼠标停留 0.6 秒才展开；离开 1 秒且没有需要看的内容就收起"""
        now = time.time()
        inside = pointer_inside()
        if inside:
            st["inside_since"] = st["inside_since"] or now
        else:
            if st["inside_since"] is not None:
                st["left_at"] = now
            st["inside_since"] = None
            kill_tip()                      # 鼠标不在窗口上，提示框一律关掉
        if st["pinned"]:
            set_expanded(True)
            return
        if not st["expanded"]:
            if inside and now - st["inside_since"] >= 0.6:
                st["hold_until"] = 0.0
                set_expanded(True)
            return
        rec = current["rec"]
        busy = bool(rec and rec.get("auto_cand"))          # 屏幕上正在三选一
        if inside or busy or manual_win["w"] is not None:
            return
        if now < st["hold_until"] or now - st["left_at"] < 1.0:
            return
        set_expanded(False)

    def toggle_pin():
        st["pinned"] = not st["pinned"]
        pin_btn.config(fg=GOLD if st["pinned"] else SUB)
        if st["pinned"]:
            set_expanded(True)

    # ---------- 识别 / 分段 / 设置菜单 ----------
    def S():            # 数据更新后 advisor.stats 会换成新的，所以每次现取
        return getattr(engine.advisor, "stats", None)
    stats_obj = S()
    scan_on = threading.Event()
    auto_default = bool(cfg.get("auto_scan", False) or getattr(engine, "auto_scan_default", False))
    if auto_default:
        scan_on.set()
    auto_var = tk.IntVar(value=1 if auto_default else 0)
    bracket_var = tk.StringVar(value=getattr(stats_obj, "dataset", "all"))
    size_var = tk.DoubleVar(value=st["k"])

    def force_scan():
        if scanner is not None and scanner.available:
            status.config(text="识别中…")
            scanner.force.set()
        else:
            status.config(text="识别不可用：" + (scanner.error if scanner else "已关闭"))

    def toggle_auto():
        scan_on.set() if auto_var.get() else scan_on.clear()
        c = load_ui_cfg()
        c["auto_scan"] = bool(auto_var.get())
        save_ui_cfg(c)

    def switch_bracket(ds=None):
        so = S()
        if so is None:
            return
        ds = ds or ("all" if so.dataset == "high" else "high")
        so.set_dataset(ds)
        bracket_var.set(ds)
        c = load_ui_cfg()
        c["bracket"] = ds
        save_ui_cfg(c)
        status.config(text="重新读取胜率…")

    menu = tk.Menu(root, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", activeforeground=FG,
                   font=F["small"], bd=0)
    sizes = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
    for label, k in (("小", 0.85), ("中", 1.0), ("大", 1.2), ("特大", 1.45)):
        sizes.add_radiobutton(label=label, variable=size_var, value=k, command=lambda k=k: set_scale(k))
    menu.add_cascade(label="字号", menu=sizes)
    if stats_obj is not None:
        br = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
        br.add_radiobutton(label="全部分段", variable=bracket_var, value="all", command=lambda: switch_bracket("all"))
        br.add_radiobutton(label="高分段", variable=bracket_var, value="high", command=lambda: switch_bracket("high"))
        menu.add_cascade(label="胜率数据分段", menu=br)
    menu.add_checkbutton(label="一直自动识别三选一（较耗 CPU）", variable=auto_var, command=toggle_auto)
    menu.add_command(label="手动输入增幅…", command=lambda: open_manual())
    menu.add_separator()

    def check_update():
        up = getattr(engine, "updater", None)
        if up is None:
            status.config(text="演示模式不检查更新")
            return
        status.config(text="检查更新中…")
        st["status_hold"] = time.time() + 20
        up.check_now()
    menu.add_command(label=f"检查更新（当前 v{APP_VERSION}）", command=check_update)
    menu.add_command(label="关闭海斗助手", command=root.destroy)

    def open_menu():
        st["hold_until"] = time.time() + 4
        menu.tk_popup(menu_btn.winfo_rootx(), menu_btn.winfo_rooty() + menu_btn.winfo_height())

    # ---------- 手动输入（小窗） ----------
    manual_win = {"w": None}
    entries = {}
    manual_vals = {"mine": "", "cand": "", "ally": "", "enemy": ""}

    def apply_all():
        for k, e in entries.items():
            manual_vals[k] = e.get()
            engine.set_manual(k, e.get())

    def open_manual():
        if manual_win["w"] is not None:
            manual_win["w"].lift()
            return
        w = tk.Toplevel(root)
        w.overrideredirect(True)
        w.attributes("-topmost", True)
        w.configure(bg=BG, highlightthickness=1, highlightbackground="#2a3140")
        tk.Label(w, text="手动输入增幅（逗号或空格分隔，可只写关键字）", bg=HEAD, fg=GOLD, font=F["small"],
                 anchor="w", padx=8, pady=4).pack(fill="x")
        for key, label in (("cand", "三选一候选"), ("mine", "我的增幅"), ("ally", "队友增幅"), ("enemy", "敌方增幅")):
            row = tk.Frame(w, bg=BG)
            row.pack(fill="x", padx=8, pady=2)
            tk.Label(row, text=label, width=8, bg=BG, fg=SUB, font=F["small"], anchor="w").pack(side="left")
            e = tk.Entry(row, bg="#1f2637", fg=FG, insertbackground=FG, relief="flat", font=F["small"], width=26)
            e.insert(0, manual_vals.get(key, ""))
            e.pack(side="left", fill="x", expand=True, ipady=2)
            e.bind("<Return>", lambda ev: apply_all())
            entries[key] = e
        btns = tk.Frame(w, bg=BG)
        btns.pack(fill="x", padx=8, pady=(4, 8))

        def close():
            apply_all()
            entries.clear()
            w.destroy()
            manual_win["w"] = None
        tk.Label(btns, text="套用并关闭", bg="#2b3a57", fg=FG, font=F["small"], padx=10, pady=3,
                 cursor="hand2").pack(side="right")
        btns.winfo_children()[-1].bind("<Button-1>", lambda e: close())
        w.update_idletasks()
        x = root.winfo_rootx() - w.winfo_reqwidth() - 6
        w.geometry(f"+{max(0, x)}+{root.winfo_rooty()}")
        manual_win["w"] = w

    # ---------- 填内容 ----------
    current = {"rec": None}

    def brief(reason):
        """卡片上的一行理由：胜率已在右上角显示，这里只留原因"""
        t = re.sub(r"(网上胜率|胜率) [\d.]+%（比平均[+-][\d.]+%）[，,]?", "", reason)
        t = re.sub(r"[，,]\s*$", "", t.replace("主流路线的下一件，", "主流路线的下一件，").strip("，, "))
        return t or reason

    def fill_rows(rows, data, cand=False, before=None):
        for i, r in enumerate(rows):
            r["fr"].pack_forget()
            if i >= len(data):
                continue
            d = data[i]
            star = "★ " if cand and i == 0 else ""
            r["sc"].config(text=str(d["score"]), fg=score_color(d["score"]))
            r["nm"].config(text=star + d["name"], fg=GOLD if cand and i == 0 else FG)
            meta = []
            if d.get("wr"):
                meta.append(f"{d['wr'] * 100:.1f}%")
            if d.get("hint"):
                meta.append(d["hint"])
            elif not d.get("known", True):
                meta.append("未收录")
            r["meta"].config(text=" · ".join(meta))
            r["rs"].config(text=short(brief(d["reason"]), 26))
            r["full"]["text"] = d["reason"] + (f"\n{d['stat_text']}" if d.get("stat_text") else "")
            if before is not None:
                r["fr"].pack(fill="x", pady=2, before=before)
            else:
                r["fr"].pack(fill="x", pady=2)

    def choose(i):
        rec = current["rec"]
        if not rec or not rec.get("cand_mode") or i >= len(rec["augs"]):
            return
        name = rec["augs"][i]["name"]
        mine = [x for x in re.split(r"[,，、\s]+", manual_vals.get("mine", "")) if x]
        if name not in mine:
            mine.append(name)
        manual_vals["mine"] = "，".join(mine)
        manual_vals["cand"] = ""
        engine.set_manual("mine", manual_vals["mine"])
        engine.set_manual("cand", "")
        engine.set_auto([])

    for i, r in enumerate(aug_rows):
        for w in (r["fr"], r["nm"], r["sc"], r["rs"], r["meta"]):
            w.bind("<Button-1>", lambda e, i=i: choose(i))

    def show(rec, flash=True):
        current["rec"] = rec
        mine_names = rec.get("my_augs", [])
        manual_vals["mine"] = "，".join(mine_names)
        summary.config(text=rec.get("summary", "").replace("｜", " · ").replace("网上 ", ""))
        # 紧急提示（人数差、残血…）
        tips = rec.get("tips", [])
        urgent = [x for x in tips if x[2]]
        if urgent:
            alert.config(text="⚠ " + urgent[0][1])
            alert.pack(fill="x", padx=8, pady=(4, 0), after=summary)
        else:
            alert.pack_forget()
        # 出装页
        normal = [x for x in tips if not x[2]][:2]
        for i, lb in enumerate(tip_lbls):
            lb.pack_forget()
            if i < len(normal):
                lb.config(text="▸" + normal[i][1])
                lb.pack(fill="x", pady=(0, 1))
        fill_rows(item_rows, rec.get("items", [])[:4])
        # 增幅页
        cand = rec.get("cand_mode")
        aug_head.config(text=("识别到三选一 · ★ 推荐 · 点卡片记为已选" if rec.get("auto_cand") else
                              "三选一评分 · ★ 推荐 · 点卡片记为已选") if cand else "当前局势推荐的增幅",
                        fg=GOLD if cand else SUB)
        mine_lbl.config(text="已选增幅：" + ("、".join(mine_names) if mine_names else "（还没有）"))
        mine_lbl.pack(fill="x", pady=(2, 0))
        fill_rows(aug_rows, rec.get("augs", [])[:3 if cand else 4], cand, before=mine_lbl)
        # 玩法页
        g = rec.get("guide") or {}
        lines = [x for x in (g.get("balance"), g.get("skills"), g.get("spells")) if x]
        lines += [f"连招  {c}\n        {note}" for c, note in g.get("combos", [])]
        if g.get("style"):
            lines.append("玩法  " + g["style"])
        guide_lbl.config(text="\n".join(lines) or "（暂无这个英雄的玩法数据）")
        # 分段 / 数据来源
        so = S()
        gv = ".".join(str(engine.gd.version).split(".")[:2])
        if so is not None:
            ver = (so.version or {}).get("version", "")
            tier = "高分段" if so.dataset == "high" else "全部分段"
            footer.config(text=f"游戏 {gv} · ARAMKit {ver} · {tier} ⇄" if ver else f"游戏 {gv} · {tier} ⇄")
        else:
            footer.config(text=f"游戏 {gv}")
        # 自动选分页：三选一 → 增幅；开局 → 玩法
        if cand:
            if st["tab"] != "augs":
                st["tab_before_cand"] = st["tab"]
                select_tab("augs")
        elif st["tab_before_cand"]:
            select_tab(st["tab_before_cand"])
            st["tab_before_cand"] = None
        elif not st["user_tab"]:
            select_tab("guide" if rec.get("game_time", 999) < 90 else "items")
        # 单行模式
        its = [x for x in rec.get("items", []) if not x.get("boots")]
        boots = next((x for x in rec.get("items", []) if x.get("boots")), None)
        if urgent:
            mini.config(text="⚠ " + urgent[0][1], fg=ORANGE)
        elif cand and rec.get("augs"):
            mini.config(text=f"★ 选 {rec['augs'][0]['name']}（{rec['augs'][0]['score']}）", fg=GOLD)
        else:
            parts = []
            if its:
                parts.append(f"▶ {its[0]['name']} {its[0]['score']}")
            if boots:
                parts.append(boots["name"])
            mini.config(text="   ".join(parts) or "等待推荐…", fg=FG)
        # 只有和你有关的推荐真的变了才弹开（别人买装备、升级不弹）
        its_key = tuple(x["name"] for x in its[:2])
        key = (its_key, boots["name"] if boots else None, bool(cand),
               tuple(x["name"] for x in rec.get("augs", [])[:3]) if cand else None)
        if flash and key != st["last_key"]:
            st["hold_until"] = time.time() + 5
            set_expanded(True)
        st["last_key"] = key
        fit()

    def poll():
        try:
            engine.overlay_rect = (root.winfo_rootx(), root.winfo_rooty(),
                                   root.winfo_rootx() + root.winfo_width(), root.winfo_rooty() + root.winfo_height())
        except tk.TclError:
            pass
        try:
            while True:
                kind, payload = engine.q.get_nowait()
                hold = time.time() < st.get("status_hold", 0)
                if kind == "rec":
                    dot.config(fg=GREEN)
                    show(payload, flash=not payload.get("quiet"))
                    if not hold:
                        set_status("")
                elif kind == "appupd":         # 程序有新版本：只提醒，点一下打开下载页
                    st["app_new"] = payload
                    set_status("")
                elif kind == "data":           # 数据版本检查 / 更新
                    st["data_msg"] = payload
                    set_status("数据已更新 ✓" if payload.startswith("数据已更新") else short(payload, 14))
                    st["status_hold"] = time.time() + 8
                    st["hold_until"] = time.time() + 6
                elif hold and payload == "监控中":
                    pass
                else:
                    if payload.startswith("等待"):
                        dot.config(fg=GREY)
                    set_status("" if payload == "监控中" else short(payload, 14))
        except queue.Empty:
            pass
        auto_collapse()
        root.after(300, poll)

    set_scale(st["k"])
    select_tab("items")
    st["hold_until"] = time.time() + 5
    stop = threading.Event()
    threading.Thread(target=engine.run, args=(stop,), daemon=True).start()
    start_scanner(engine, scanner, stop, scan_on)
    root.after(300, poll)
    root.mainloop()
    stop.set()


# --------------------------------------------------------------------------------------
# 网页检视（手机 / 第二屏幕；独占全屏时用）
# --------------------------------------------------------------------------------------
def lan_ip():
    import socket
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:  # noqa
        return "127.0.0.1"


def start_web(engine, port=8765):
    import html
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    def page():
        rec = engine.history[-1] if engine.history else None
        esc = html.escape

        def rows(data, cand=False):
            out = []
            for i, d in enumerate(data[:5]):
                col = "#4ade80" if d["score"] >= 80 else "#facc15" if d["score"] >= 60 else "#94a3b8"
                star = "★ " if cand and i == 0 else ""
                bits = ([f"胜率{d['wr'] * 100:.1f}%"] if d.get("wr") else []) + ([d["hint"]] if d.get("hint") else [])
                hint = f' <small style="color:#9aa4b5">{esc(" · ".join(bits))}</small>' if bits else ""
                out.append(f'<div class="c"><div class="t"><b>{star}{esc(d["name"])}{hint}</b>'
                           f'<span style="color:{col}">{d["score"]}</span></div><p>{esc(d["reason"])}</p></div>')
            return "".join(out)
        if not rec:
            content = "<p class='s'>等待对局…</p>"
        else:
            at = ("识别到三选一（★ 推荐）" if rec["cand_mode"] else "推荐增幅")
            tips = "".join(f"<div class='c' style='color:{'#fb923c' if u else '#e8ecf3'}'>{'⚠' if u else '•'} {esc(x)}</div>"
                           for _, x, u in rec.get("tips", []))
            g = rec.get("guide") or {}
            gl = [x for x in (g.get("balance"), g.get("skills"), g.get("spells")) if x] + \
                 [f"连招：{c}｜{n}" for c, n in g.get("combos", [])] + ([f"玩法：{g['style']}"] if g.get("style") else [])
            guide = "".join(f"<div class='c'>{esc(x)}</div>" for x in gl)
            content = (f"<p class='ch'>[{rec['time']}] {esc('；'.join(rec['changes'][:3]))}</p>"
                       f"<p class='s'>{esc(rec['summary'])}</p><h3>英雄玩法</h3>{guide}<h3>战术建议</h3>{tips}"
                       f"<h3>推荐装备</h3>{rows(rec['items'])}"
                       f"<h3>{at}</h3>{rows(rec['augs'], rec['cand_mode'])}")
        return ("<!doctype html><meta charset='utf-8'><meta name='viewport' content='width=device-width'>"
                "<meta http-equiv='refresh' content='2'><title>海斗助手</title><style>"
                "body{background:#12161f;color:#e8ecf3;font-family:system-ui,sans-serif;margin:12px;font-size:16px}"
                "h3{margin:14px 0 6px}.c{background:#1a2030;border-radius:8px;padding:8px 10px;margin:6px 0}"
                ".t{display:flex;justify-content:space-between;font-size:17px}.t span{font-weight:700;font-size:20px}"
                "p{margin:4px 0;color:#9aa4b5;font-size:14px}.ch{color:#c8aa6e}.s{font-size:13px}</style>"
                "<h2 style='color:#c8aa6e;margin:0'>⚔ 海斗助手</h2>" + content)

    class H(BaseHTTPRequestHandler):
        def do_GET(self):
            body = page().encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass

    srv = ThreadingHTTPServer(("0.0.0.0", port), H)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    url = f"http://{lan_ip()}:{port}"
    print(f"[网页] 手机/平板连同一个 WiFi，浏览器开启：{url}")
    return url


# --------------------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser(description="海斗助手：海克斯大乱斗实时出装/增幅推荐")
    ap.add_argument("--mock", action="store_true", help="使用模拟对局演示")
    ap.add_argument("--console", action="store_true", help="控制台文字模式")
    ap.add_argument("--lang", default="zh_MY", help="数据语言，默认 zh_MY（简体字＋台服用语，和游戏客户端一致），可改 zh_TW / zh_CN")
    ap.add_argument("--interval", type=float, default=1.5, help="轮询间隔秒数")
    ap.add_argument("--alpha", type=float, default=0.88, help="悬浮窗透明度 0.3~1")
    ap.add_argument("--no-scan", action="store_true", help="关闭屏幕识别三选一")
    ap.add_argument("--no-stats", action="store_true", help="不使用网上胜率数据")
    ap.add_argument("--no-click", action="store_true", help="不自动记录你点选的增幅")
    ap.add_argument("--hotkey", default="F8", help="识别三选一的快捷键（F1~F12），默认 F8")
    ap.add_argument("--auto-scan", action="store_true", help="一直自动识别三选一（较耗 CPU）")
    ap.add_argument("--bracket", choices=["all", "high"], default=None, help="胜率数据分段：all 全部 / high 高分段")
    ap.add_argument("--web", action="store_true", help="同时开启网页检视（手机/第二屏，埠 8765）")
    ap.add_argument("--scale", type=float, default=None, help="界面缩放，例如 1.3")
    args = ap.parse_args()

    if sys.platform.startswith("win"):
        try:  # 高分屏下截图坐标与实际一致
            import ctypes
            ctypes.windll.shcore.SetProcessDpiAwareness(2)
        except Exception:  # noqa
            pass
        try:  # 降低本程序的 CPU 优先级，游戏永远优先
            import ctypes
            ctypes.windll.kernel32.SetPriorityClass(ctypes.windll.kernel32.GetCurrentProcess(), 0x4000)
        except Exception:  # noqa
            pass
    print(f"海斗助手 v{APP_VERSION}")
    gd, stats = load_all(args.lang, args.bracket or load_ui_cfg().get("bracket", "all"), not args.no_stats)
    clean_old_cache(data_versions(gd, stats))
    source = MockGame() if args.mock else LiveSource()
    engine = Engine(gd, source, args.interval, stats)
    scanner = None
    if not args.no_scan:
        scanner = MockScanner(source) if args.mock else ScreenScanner(engine.advisor)
        if not args.no_click:
            engine.clicker = MockClickWatcher(source) if args.mock else ClickWatcher()
        engine.hotkey = None if args.mock else HotkeyWatcher(args.hotkey)
        engine.auto_scan_default = args.auto_scan or args.mock   # 演示模式自动识别
    if not args.mock:
        start_updater(engine, args.lang, not args.no_stats, threading.Event())
    if args.web:
        start_web(engine)
    if args.console:
        run_console(engine, scanner)
        return
    try:
        run_overlay(engine, args.alpha, scanner, args.scale)
    except ImportError:
        print("未找到 tkinter，改用控制台模式")
        run_console(engine, scanner)


if __name__ == "__main__":
    main()
